#!/usr/bin/env python3

redNum, blueNum = map(int, input().split())

def simulate(red, redCount, blueCount, petyaMove):
    petya, vasya = 0, 0
    while redCount + blueCount > 0:
        wasRed = red
        if petyaMove and red and redCount > 0:
            red = True
        elif petyaMove and not red and blueCount > 0:
            red = False
        elif not petyaMove and red and blueCount > 0:
            red = False
        elif not petyaMove and not red and redCount > 0:
            red = True
        elif redCount > 0:
            red = True
        else:
            red = False
        if red:
            redCount -= 1
            if wasRed:
                petya += 1
            else:
                vasya += 1
        else:
            blueCount -= 1
            if wasRed:
                vasya += 1
            else:
                petya += 1
        petyaMove = not petyaMove
    return petya, vasya

petya0, vasya0 = simulate(True, redNum - 1, blueNum, False)
petya1, vasya1 = simulate(False, redNum, blueNum - 1, False)

if petya0 > petya1:
    print(f"{petya0} {vasya0}")
else:
    print(f"{petya1} {vasya1}")

